{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.rar_sales_and_marketing_summary as with marketing_spends as ( select upper(channel) as Channel, \'WEBSITE\' as marketplace, upper(campaign_name) as campaign_name, upper(sku) as sku, date, sum(ifnull(spend,0)) as marketing_spend from `rainandrainbow-wh.maplemonk.rar_wh_main_product_google_ads_consolidated` group by 1,2,3,4,5 union all select upper(channel) as Channel, \'WEBSITE\' as marketplace, upper(campaign_name) as campaign_name, upper(sku) as sku, date, sum(ifnull(spend,0)) as marketing_spend from `rainandrainbow-wh.maplemonk.rar_wh_main_product_facebook_consolidated` group by 1,2,3,4,5 ), sales as ( select distinct case when upper(CHANNEL) like any (\'%META%\',\'%FACEBOOK%\',\'%INSTAGRAM%\',\'%IG%\',\'%FB%\') then \'FACEBOOK\' when upper(CHANNEL) like \'%GOOGLE%\' then \'GOOGLE\' else upper(channel) end as channel, case when upper(marketplace) like \'%SHOPIFY%\' then \'WEBSITE\' end as marketplace, upper(utm_campaign) as final_utm_campaign, upper(commonsku) as commonsku, date(order_date) as date, sum(ifnull(selling_price,0)) as total_sales from maplemonk.rainandrainbow_wh_sales_consolidated where upper(marketplace) like \'%SHOPIFY%\' group by 1,2,3,4,5 ), latest_inventory AS ( select replace(i.skucode,\'`\',\'\') as sku, sum(cast(inventory as int64)) as closing_inventory from `rainandrainbow-wh.maplemonk.unicommerce_rainandrainbow_unicommerce_get_inventory_snapshot` i where date(datetime_sub(parse_timestamp(\'%Y-%m-%dT%H:%M:%E*S%Ez\', i.timestamp), interval 8 hour)) = ( select max(date(datetime_sub(parse_timestamp(\'%Y-%m-%dT%H:%M:%E*S%Ez\', timestamp), interval 8 hour))) from `rainandrainbow-wh.maplemonk.unicommerce_rainandrainbow_unicommerce_get_inventory_snapshot` ) group by 1 ), daily_channel_sales as ( select date, marketplace, channel, sum(total_sales) as daily_total_sales from sales group by 1, 2, 3 ), sku_channel_sales as ( select date, marketplace, channel, commonsku as sku, sum(total_sales) as sku_daily_sales from sales group by 1, 2, 3, 4 ), sku_sales_proportion as ( select s.date, s.marketplace, s.channel, s.sku, s.sku_daily_sales, d.daily_total_sales, safe_divide(s.sku_daily_sales, d.daily_total_sales) as sales_weight from sku_channel_sales s left join daily_channel_sales d on s.date = d.date and s.marketplace = d.marketplace and s.channel = d.channel ), direct_spends as ( select date, marketplace, channel, campaign_name, sku, marketing_spend from marketing_spends where sku is not null and sku != \'\' and sku != \'null\' ), general_spends as ( select date, marketplace, channel, campaign_name, marketing_spend from marketing_spends where sku is null or sku = \'\' or sku = \'null\' ), allocated_spends as ( select g.date, g.marketplace, g.channel, g.campaign_name, p.sku, case when p.sales_weight is null then g.marketing_spend else g.marketing_spend * p.sales_weight end as marketing_spend from general_spends g left join sku_sales_proportion p on g.date = p.date and g.marketplace = p.marketplace and g.channel = p.channel ), total_sku_spends as ( select date, marketplace, channel, campaign_name, sku, sum(marketing_spend) as spends from ( select * from direct_spends union all select * from allocated_spends ) group by 1, 2, 3, 4, 5 ), total_sku_sales as ( select date, marketplace, channel, final_utm_campaign as campaign_name, commonsku as sku, sum(total_sales) as total_sales from sales group by 1, 2, 3, 4, 5 ) select coalesce(sp.date, sa.date) as date, coalesce(sp.marketplace, sa.marketplace) as marketplace, coalesce(sp.channel, sa.channel) as marketing_channel, coalesce(sp.campaign_name, sa.campaign_name) as campaign_name, coalesce(sp.sku, sa.sku) as sku, sm.category, sm.url, ifnull(max(inv.closing_inventory), 0) as closing_inventory, sum(ifnull(sp.spends, 0)) as spends, sum(ifnull(sa.total_sales, 0)) as sales from total_sku_spends sp full outer join total_sku_sales sa on sp.date = sa.date and sp.marketplace = sa.marketplace and sp.channel = sa.channel and ifnull(sp.campaign_name, \'\') = ifnull(sa.campaign_name, \'\') and ifnull(sp.sku, \'\') = ifnull(sa.sku, \'\') left join (select upper(trim(sku_code)) sku, upper(category) as category, url from maplemonk.rar_sku_master qualify row_number() over (partition by upper(trim(sku_code)) order by 1 desc)=1 ) sm on sm.sku = coalesce(sp.sku, sa.sku) left join latest_inventory inv on inv.sku = coalesce(sp.sku, sa.sku) group by 1, 2, 3, 4, 5, 6, 7 order by date desc, sales desc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            